// Golden test: the JS decoder must reproduce the Python decoder's output for every
// case in tests/golden/*.json (generated by scripts/gen_golden.py), except
//   * cases where Python raises  -> JS must not throw and must still produce output
//   * cases in known_diffs/*.json -> intentional bug fixes, each with a reason
import { describe, it, expect } from 'vitest';
const golden = Object.values(import.meta.glob('./golden/*.json', { eager: true, import: 'default' })).flat();
const knownDiffs = Object.values(import.meta.glob('./known_diffs/*.json', { eager: true, import: 'default' })).flat();
import { createContext } from '../src/core/context.js';
import { decodePacket, normalizeHex } from '../src/core/decoder.js';
import { resolveVendor } from '../src/core/registry.js';
import { renderText } from '../src/render/text.js';

const keyOf = (c) => [resolveVendor(c.vendor), ...(c.prev || []).map(normalizeHex), normalizeHex(c.hex)].join('|');
const known = new Map(knownDiffs.map((d) => [keyOf(d), d.reason]));

// Cosmetic-only normalisation (trailing spaces, repeated spaces, unbalanced parens,
// trailing blank lines) so fixing e.g. a missing ")" doesn't need a known_diffs entry.
export function normalizeOutput(text) {
  return text
    .split('\n')
    .map((l) => l.replace(/[()]/g, '').replace(/ {2,}/g, ' ').trimEnd())
    .join('\n')
    .replace(/\n+$/, '');
}

function runCase(c) {
  const ctx = createContext(resolveVendor(c.vendor));
  for (const p of c.prev || []) decodePacket(p, ctx, 2);
  return renderText(decodePacket(c.hex, ctx, 2));
}

const label = (c) => `[${c.vendor}] ${c.hex}${c.prev?.length ? ` (after ${c.prev.join(', ')})` : ''}  <${c.source}>`;

describe('known_diffs entries refer to existing golden cases', () => {
  const goldenKeys = new Set(golden.map(keyOf));
  it('no orphan entries', () => {
    expect(knownDiffs.filter((d) => !goldenKeys.has(keyOf(d))).map((d) => `${d.vendor} ${d.hex}`)).toEqual([]);
  });
});

describe('golden corpus vs Python decoder', () => {
  for (const c of golden) {
    const k = keyOf(c);
    if (c.error) {
      it(`python raises, JS must not: ${label(c)}`, () => {
        expect(() => runCase(c)).not.toThrow();
      });
    } else if (known.has(k)) {
      // a known diff must still differ - once Python is fixed too, delete the entry
      it(`known diff still differs (${known.get(k)}): ${label(c)}`, () => {
        expect(normalizeOutput(runCase(c)), 'stale known_diffs entry: JS now matches Python, remove it').not.toBe(normalizeOutput(c.output));
      });
    } else {
      it(label(c), () => {
        expect(normalizeOutput(runCase(c))).toBe(normalizeOutput(c.output));
      });
    }
  }
});
